// Generate JWT token for each user
const crypto = require('crypto');

// Get JWT_SECRET from environment variable
const JWT_SECRET = $env.JWT_SECRET;

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is not set');
}

// Base64URL encode function
function base64UrlEncode(str) {
  return Buffer.from(str)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Create HMAC-SHA256 signature
function createSignature(input, secret) {
  return crypto
    .createHmac('sha256', secret)
    .update(input)
    .digest('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Generate JWT token
function generateJWT(userId, secret) {
  const header = {
    alg: 'HS256',
    typ: 'JWT'
  };

  const now = Math.floor(Date.now() / 1000);
  const payload = {
    sub: userId,
    date: new Date().toISOString().split('T')[0], // YYYY-MM-DD
    iat: now,
    exp: now + (24 * 60 * 60) // 24 hours from now
  };

  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encodedPayload = base64UrlEncode(JSON.stringify(payload));
  const signature = createSignature(`${encodedHeader}.${encodedPayload}`, secret);

  return `${encodedHeader}.${encodedPayload}.${signature}`;
}

// Process each item
const items = $input.all();
const results = [];

for (const item of items) {
  const userId = item.json.user_id;
  const token = generateJWT(userId, JWT_SECRET);

  // Build the workout URL
  const workoutUrl = `https://app.gymbot.co/w?t=${token}`;

  results.push({
    json: {
      ...item.json,
      token: token,
      workout_url: workoutUrl
    }
  });
}

return results;

